from core3 import Q,R,load,dump,METHODS
import csv,json,datetime,hashlib

def main():
 designs=load(Q/'rtl/design_manifest.json');ppa=load(Q/'results/hardware/ppa.json');by={r['top']:r for r in ppa};assert len(ppa)==sum(not e['duplicate_of']for e in designs);rows=[];groups=[];scans=[]
 for e in designs:
  r=by[e['duplicate_of']or e['top']];raw=list(csv.DictReader((Q/f'results/{e["case"]}_replay.csv').open()));mi=METHODS.index(e['method']);f=next(x for x in raw if int(x['method'])==mi and x['stage']=='final');assert int(f['WCE'])<=e['budget']
  if e['method']=='exact_joint':assert int(f['seed_max_delta'])==0
  pairs=load(Q/f'graphs/{e["case"]}_pairs.json')
  rows.append(dict(case=e['case'],method=e['method'],LUT=r['LUT'],WCE=e['WCE'],budget=e['budget'],seed_max_delta=int(f['seed_max_delta']),merges=len(e['choices']),strict_merges=sum(pairs[pi]['candidate_class']=='strict_new'for pi,m in e['choices']),FF=r['FF'],CARRY4=r['CARRY4'],DSP=r['DSP'],clock_ns=r['clock_ns'],WNS_ns=r['WNS_ns'],WHS_ns=r['WHS_ns'],FF_period_ns=r['FF_period_ns'],pass_registered_clock=r['pass_registered_clock'],MAE_at_lowbits_zero=float(f['MAE_at_lowbits_zero']),error_count_at_lowbits_zero=int(f['error_count_at_lowbits_zero']),inputs=int(f['inputs'])))
 for c in load(Q/'configs/plan.json')['cases']:
  name=c['name'];rr={r['method']:r for r in rows if r['case']==name};pairs=load(Q/f'graphs/{name}_pairs.json');records=load(Q/f'results/{name}_methods.json');scans+=list(csv.DictReader((Q/f'results/{name}_replay.csv').open()));subset=[r for r in records if pairs[r['pair']]['candidate_class']=='strict_new'];bd=next(e for e in designs if e['case']==name and e['method']=='budget_joint');accepted={pi for pi,m in bd['choices']};extra=[r['pair']for r in subset if r['methods']['budget_joint']is not None and r['methods']['exact_joint']is None];joint_only=[r['pair']for r in subset if r['methods']['budget_joint']is not None and r['methods']['serial']is None]
  groups.append(dict(case=name,LUT={m:r['LUT']for m,r in rr.items()},gain_vs_exact_pct=100*(rr['exact_joint']['LUT']-rr['budget_joint']['LUT'])/rr['exact_joint']['LUT'],gain_vs_serial_pct=100*(rr['serial']['LUT']-rr['budget_joint']['LUT'])/rr['serial']['LUT'],strict_registered=len(subset),strict_context_eligible={m:sum(r['methods'][m]is not None for r in subset)for m in METHODS},strict_budget_extra_pair_ids=extra,strict_joint_only_pair_ids=joint_only,strict_budget_extra_admitted=sorted(accepted&set(extra)),strict_joint_only_admitted=sorted(accepted&set(joint_only)),both_single_edits_violate_sample_budget=[r['pair']for r in records if r['pair']in accepted and r['methods']['budget_joint']['both_single_edits_violate_sample_budget']],timing_pass={m:r['pass_registered_clock']for m,r in rr.items()},optimizer_seconds=load(Q/f'state/{name}_optimize.json')['seconds']))
 data=dict(round=3,status='COMPLETE_AWAIT_SCORE',completed=datetime.datetime.now().astimezone().isoformat(),rows=rows,cases=groups,full_domain_scans=len(scans),effective_inputs_evaluated=sum(int(r['inputs'])for r in scans),unique_physical_jobs=len(ppa),hdl=load(Q/'state/rtl_validation.json'),scope='fixed identical R2 seeds; exact-output relation and serial baselines; budget relation innovation; 8 controls plus 16 strict pairs; sample proposals and full-domain admission; same 10ns/25ns clocks',limits=['absence of a legal configuration is limited to registered pins/menu; not unrestricted impossibility','serial is a specified greedy reference, not complete author-flow reproduction or all possible sequential methods','pair context may become stale after combined changes; only whole-domain admitted final designs establish WCE','single-edit budget violation witnesses concern the selected joint function, not all alternative sequential functions','one default route per design; no placement robustness claim','four cases cover only multiplier and square-root families'])
 dump(Q/'state/analysis.json',data)
 with(Q/'reports/RESULTS.csv').open('w',newline='')as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 hashes={p.relative_to(Q).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()for sub in ['tools','configs','src','rtl','graphs','results']for p in(Q/sub).rglob('*')if p.is_file()and p.suffix in['.py','.tcl','.json','.cpp','.v','.sv','.xdc','.csv','.hex','.log','.rpt','.stderr']};dump(Q/'state/evidence_hashes.json',hashes);print(json.dumps(groups,indent=2));print('full scans',len(scans))
if __name__=='__main__':main()
